using BULA;
using BULA.Gallery;
using BULA.Sparse;
using NUnit.Framework;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// Validates the sparse (BSR) gallery generators (floatRandomSparseSPD / floatRandomSparse) by their
// defining property, exercised through the solvers that consume them:
//   - SPD generator: build A, form b = A*x_known, solve with CG -> recovers x_known. CG converges only
//     for SPD, so success is proof the generator is symmetric positive-definite (not just symmetric).
//   - Tall generator: build A (m > n), form a CONSISTENT b = A*x_known, solve the least-squares problem
//     with LSQR -> recovers x_known. That requires full column rank, so success proves it.
// Runs inside a [BurstCompile] IJob (matches floatSparseSolverTests); the generators are themselves
// Burst-compatible (no managed collections -- Unity.Mathematics.Random + builder only).
public class floatSparseGalleryTests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct SparseGalleryTestJob : IJob
    {
        public enum TestType
        {
            RandomSparseSPDRecoversViaCG,
            RandomSparseTallRecoversViaLsqr,
        }

        public TestType Type;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.RandomSparseSPDRecoversViaCG:     RandomSparseSPDRecoversViaCG();     break;
                case TestType.RandomSparseTallRecoversViaLsqr:  RandomSparseTallRecoversViaLsqr();  break;
            }
        }

        // Recovery tol = achievable CG/LSQR solution accuracy: the solvers converge on the RESIDUAL to
        // sqrt(eps), so the SOLUTION error is ~kappa*sqrt(eps) (kappa ~ tens for these diag-dominant
        // matrices) -- ~1e-3 in float, ~1e-6 in double. (A tighter double bound like 1e-8 would test the
        // solver's conditioning, not the generator.)
        static float Tol() => 2e-3f;

        void RandomSparseSPDRecoversViaCG()
        {
            int blockRows = 10, BR = 3;
            int n = blockRows * BR;
            var A = floatGallery.floatRandomSparseSPD(blockRows, BR, (float)0.5f, 20260708u);

            var xKnown = GenerateOP.floatRandomVec(n, 1f, 3f, 777);
            var b = BSR.spMV(in A, in xKnown);

            var x = new floatN(n, Allocator.Temp);
            bool ok = Krylov.cg(in A, in b, ref x, 8 * n, Consts.floatSqrtEps);
            Assert.IsTrue(ok);                                   // CG converged => A is SPD

            var diff = new floatN(in xKnown, Allocator.Temp);
            floatComp.subInPlace(diff, x);
            Assert.IsTrue(Analysis.isZero(diff, Tol()));         // and recovered the exact solution
        }

        void RandomSparseTallRecoversViaLsqr()
        {
            int blockRows = 16, blockCols = 8, BR = 2;           // 32 x 16 tall
            int n = blockCols * BR;
            var A = floatGallery.floatRandomSparse(blockRows, blockCols, BR, (float)0.5f, 4242u);

            var xKnown = GenerateOP.floatRandomVec(n, 1f, 3f, 99);
            var b = BSR.spMV(in A, in xKnown);                   // consistent (b in range(A))

            var x = new floatN(n, Allocator.Temp);
            bool ok = Krylov.lsqr(in A, in b, ref x, 16 * n, Consts.floatSqrtEps);
            Assert.IsTrue(ok);                                   // LSQR converged => full column rank

            var diff = new floatN(in xKnown, Allocator.Temp);
            floatComp.subInPlace(diff, x);
            Assert.IsTrue(Analysis.isZero(diff, Tol()));
        }
    }

    [Test]
    public void RandomSparseSPDRecoversViaCG()
        => new SparseGalleryTestJob { Type = SparseGalleryTestJob.TestType.RandomSparseSPDRecoversViaCG }.Run();

    [Test]
    public void RandomSparseTallRecoversViaLsqr()
        => new SparseGalleryTestJob { Type = SparseGalleryTestJob.TestType.RandomSparseTallRecoversViaLsqr }.Run();
}
